int c[N][N];
void initC(int n){
    for(int i=0;i<=n;i++){
        c[i][0]=c[i][i]=1;
        for(int j=1;j<i;j++){
            c[i][j]=c[i-1][j-1]+c[i-1][j];
        }
    }
}

// 去前导零
string rz(string s){
    int idx=0;
    while(idx<s.size() && s[idx]=='0') {
        idx++;
    }
    if(idx==s.size()){
        return "0";
    }
    return s.substr(idx);
}

