// 高精度计算2的n次方
big mul3(int x){ 
    big z;
    z.num[0]=1; 
    z.size=x;
    for(int j=1;j<=x;j++){
        int temp=0;
        for(int i=0;i<z.size;i++){
            z.num[i]=2*z.num[i]+temp;
            temp=z.num[i]/10;
            z.num[i]%=10;
        }
    }
    return z;
}

// 高精度阶乘
big mul4(int x){ 
    big z;
    z.num[0]=1;
    z.size=1;
    for(int j=2;j<=x;j++){
        int temp=0;
        for(int i=0;i<z.size;i++){
            z.num[i]=j*z.num[i]+temp;
            temp=z.num[i]/10;
            z.num[i]%=10;
        }
        while(temp>0){
            z.num[z.size]=temp%10;
            temp/=10;
            z.size++;
        }
    }
    clean(z);
    return z;
}

// 高精度比较
bool cmp(big x,big y){
    clean(x);
    clean(y);
    if(x.size!=y.size) return x.size>y.size;
    else{
        for(int i=x.size-1;i>=0;i--){
            if(x.num[i]!=y.num[i]){
                return x.num[i]>y.num[i];
            }
        }
    }
}
